    "mysql": "WITH\n    t AS (\n        SELECT\n            visited_on,\n            SUM(amount) OVER (\n                ORDER BY visited_on\n                ROWS 6 PRECEDING\n            ) AS amount,\n            RANK() OVER (\n                ORDER BY visited_on\n                ROWS 6 PRECEDING\n            ) AS rk\n        FROM\n            (\n                SELECT visited_on, SUM(amount) AS amount\n                FROM Customer\n                GROUP BY visited_on\n            ) AS tt\n    )\nSELECT visited_on, amount, ROUND(amount / 7, 2) AS average_amount\nFROM t\nWHERE rk > 6;",
    "postgres": "WITH\n    t AS (\n        SELECT\n            visited_on,\n            SUM(amount) OVER (\n                ORDER BY visited_on\n                ROWS 6 PRECEDING\n            ) AS amount,\n            RANK() OVER (\n                ORDER BY visited_on\n                ROWS 6 PRECEDING\n            ) AS rk\n        FROM\n            (\n                SELECT visited_on, SUM(amount) AS amount\n                FROM Customer\n                GROUP BY visited_on\n            ) AS tt\n    )\nSELECT visited_on, amount, ROUND(amount / 7, 2) AS average_amount\nFROM t\nWHERE rk > 6;",
    "postgresStatus": "portable",
