    "title": "Count Salary Categories",
    "slug": "count-salary-categories",
    "difficulty": "Medium",
    "premium": false,
    "pattern": "aggregation",
    "summary": "Solve Count Salary Categories with the aggregation & having pattern.",
    "mysql": "WITH\n    S AS (\n        SELECT 'Low Salary' AS category\n        UNION\n        SELECT 'Average Salary'\n        UNION\n        SELECT 'High Salary'\n    ),\n    T AS (\n        SELECT\n            CASE\n                WHEN income < 20000 THEN \"Low Salary\"\n                WHEN income > 50000 THEN 'High Salary'\n                ELSE 'Average Salary'\n            END AS category,\n            COUNT(1) AS accounts_count\n        FROM Accounts\n        GROUP BY 1\n    )\nSELECT category, IFNULL(accounts_count, 0) AS accounts_count\nFROM\n    S\n    LEFT JOIN T USING (category);",
    "postgres": "WITH categories(category) AS (\n  VALUES ('Low Salary'), ('Average Salary'), ('High Salary')\n), counts AS (\n  SELECT\n    CASE\n      WHEN income < 20000 THEN 'Low Salary'\n      WHEN income > 50000 THEN 'High Salary'\n      ELSE 'Average Salary'\n    END AS category,\n    COUNT(*) AS accounts_count\n  FROM Accounts\n  GROUP BY 1\n)\nSELECT c.category, COALESCE(n.accounts_count, 0) AS accounts_count\nFROM categories AS c\nLEFT JOIN counts AS n USING (category);",
    "postgresStatus": "verified-adaptation",
