    "pattern": "strings",
    "summary": "Solve Find Invalid IP Addresses with the strings & regular expressions pattern.",
    "mysql": "SELECT\n    ip,\n    COUNT(*) AS invalid_count\nFROM logs\nWHERE\n    LENGTH(ip) - LENGTH(REPLACE(ip, '.', '')) != 3\n    OR SUBSTRING_INDEX(ip, '.', 1) REGEXP '^0[0-9]'\n    OR SUBSTRING_INDEX(SUBSTRING_INDEX(ip, '.', 2), '.', -1) REGEXP '^0[0-9]'\n    OR SUBSTRING_INDEX(SUBSTRING_INDEX(ip, '.', 3), '.', -1) REGEXP '^0[0-9]'\n    OR SUBSTRING_INDEX(ip, '.', -1) REGEXP '^0[0-9]'\n    OR SUBSTRING_INDEX(ip, '.', 1) > 255\n    OR SUBSTRING_INDEX(SUBSTRING_INDEX(ip, '.', 2), '.', -1) > 255\n    OR SUBSTRING_INDEX(SUBSTRING_INDEX(ip, '.', 3), '.', -1) > 255\n    OR SUBSTRING_INDEX(ip, '.', -1) > 255\nGROUP BY 1\nORDER BY 2 DESC, 1 DESC;",
    "postgres": "SELECT ip, COUNT(*) AS invalid_count\nFROM logs\nWHERE NOT (\n  ip ~ '^[0-9]+(\\.[0-9]+){3}$'\n  AND NOT EXISTS (\n    SELECT 1\n    FROM UNNEST(STRING_TO_ARRAY(ip, '.')) AS octet(value)\n    WHERE value::int > 255\n       OR (LENGTH(value) > 1 AND value LIKE '0%')\n  )\n)\nGROUP BY ip\nORDER BY invalid_count DESC, ip DESC;",
    "postgresStatus": "verified-adaptation",
    "why": "The query makes the required output grain explicit, then applies text-processing logic before the final projection and ordering.",
    "edge": "Test case, whitespace, punctuation, empty strings, collation, and regex anchoring.",
    "source": "doocs/leetcode"
