    "summary": "Solve Find Consistently Improving Employees with the joins & self-joins pattern.",
    "mysql": "WITH\n    recent AS (\n        SELECT\n            employee_id,\n            review_date,\n            ROW_NUMBER() OVER (\n                PARTITION BY employee_id\n                ORDER BY review_date DESC\n            ) AS rn,\n            (\n                LAG(rating) OVER (\n                    PARTITION BY employee_id\n                    ORDER BY review_date DESC\n                ) - rating\n            ) AS delta\n        FROM performance_reviews\n    )\nSELECT\n    employee_id,\n    name,\n    SUM(delta) AS improvement_score\nFROM\n    recent\n    JOIN employees USING (employee_id)\nWHERE rn > 1 AND rn <= 3\nGROUP BY 1\nHAVING COUNT(*) = 2 AND MIN(delta) > 0\nORDER BY 3 DESC, 2;",
    "postgres": "WITH\n    recent AS (\n        SELECT\n            employee_id,\n            review_date,\n            ROW_NUMBER() OVER (\n                PARTITION BY employee_id\n                ORDER BY review_date DESC\n            ) AS rn,\n            (\n                LAG(rating) OVER (\n                    PARTITION BY employee_id\n                    ORDER BY review_date DESC\n                ) - rating\n            ) AS delta\n        FROM performance_reviews\n    )\nSELECT\n    employee_id,\n    name,\n    SUM(delta) AS improvement_score\nFROM\n    recent\n    JOIN employees USING (employee_id)\nWHERE rn > 1 AND rn <= 3\nGROUP BY 1\nHAVING COUNT(*) = 2 AND MIN(delta) > 0\nORDER BY 3 DESC, 2;",
