    "difficulty": "Medium",
    "premium": false,
    "pattern": "joins",
    "summary": "Solve Find Overbooked Employees with the joins & self-joins pattern.",
    "mysql": "WITH\n    week_meeting_hours AS (\n        SELECT\n            employee_id,\n            YEAR(meeting_date) AS year,\n            WEEK(meeting_date, 1) AS week,\n            SUM(duration_hours) hours\n        FROM meetings\n        GROUP BY 1, 2, 3\n    ),\n    intensive_weeks AS (\n        SELECT\n            employee_id,\n            employee_name,\n            department,\n            count(1) AS meeting_heavy_weeks\n        FROM\n            week_meeting_hours\n            JOIN employees USING (employee_id)\n        WHERE hours >= 20\n        GROUP BY 1\n    )\nSELECT employee_id, employee_name, department, meeting_heavy_weeks\nFROM intensive_weeks\nWHERE meeting_heavy_weeks >= 2\nORDER BY 4 DESC, 2;",
    "postgres": "WITH\n    week_meeting_hours AS (\n        SELECT\n            employee_id,\n            EXTRACT(YEAR FROM meeting_date) AS year,\n            WEEK(meeting_date, 1) AS week,\n            SUM(duration_hours) hours\n        FROM meetings\n        GROUP BY 1, 2, 3\n    ),\n    intensive_weeks AS (\n        SELECT\n            employee_id,\n            employee_name,\n            department,\n            count(1) AS meeting_heavy_weeks\n        FROM\n            week_meeting_hours\n            JOIN employees USING (employee_id)\n        WHERE hours >= 20\n        GROUP BY 1\n    )\nSELECT employee_id, employee_name, department, meeting_heavy_weeks\nFROM intensive_weeks\nWHERE meeting_heavy_weeks >= 2\nORDER BY 4 DESC, 2;",
    "postgresStatus": "portable",
